import Foundation
public enum URLNormalizationError: Error, Sendable { case invalidScheme; case missingHost; case invalidURL }
public enum URLNormalizer { public static func normalize(_ raw:String)throws->URL{let value=raw.trimmingCharacters(in:.whitespacesAndNewlines).trimmingCharacters(in:CharacterSet(charactersIn:"/")); guard let url=URL(string:value), let scheme=url.scheme?.lowercased(), scheme=="http" || scheme=="https" else{throw URLNormalizationError.invalidScheme}; guard url.host != nil else{throw URLNormalizationError.missingHost}; return url} public static func endpoint(base:URL,path:String,query:[URLQueryItem]=[])->URL{var u=base.appendingPathComponent(path.hasPrefix("/") ? String(path.dropFirst()):path);if !query.isEmpty{var c=URLComponents(url:u,resolvingAgainstBaseURL:false);c?.queryItems=query;u=c?.url ?? u};return u} }
